/* text entity of a sketch → closed outline loops in sketch coordinates.
   e: { t: 'text', s: string, x, y (left end of the baseline), h: capital letter height in mm, a: angle (deg), bold, sp: letter spacing (mm) } */
function skicaTextLoops(e) {
  const F = SKICA_FONTS[e.bold === false ? 'sans' : 'bold'], H = F.g.H, out = [];
  if (!H || !e.s || !(e.h > 0)) return out;
  let cap = 0; for (const c of H[1]) for (let i = 1; i < c.length; i += 2) cap = Math.max(cap, c[i]);
  const k = e.h / (cap || 730), a = (e.a || 0) * Math.PI / 180, ca = Math.cos(a), sa = Math.sin(a), sp = Number(e.sp) || 0;
  const lines = String(e.s).split('\n'), lh = e.h * 1.5;
  lines.forEach((line, li) => {
    let x = 0;
    for (const ch of line) {
      const g = F.g[ch] || F.g['?'];
      for (const c of g[1]) {
        const pts = [];
        for (let i = 0; i < c.length; i += 2) {
          const lx = x + c[i] * k, ly = c[i + 1] * k - li * lh;
          pts.push([Math.round((e.x + lx * ca - ly * sa) * 1e4) / 1e4, Math.round((e.y + lx * sa + ly * ca) * 1e4) / 1e4]);
        }
        out.push(pts);
      }
      x += g[0] * k + sp;
    }
  });
  return out;
}
/* overall size of the text (width of the longest line, height of the lines) in mm, before rotation */
function skicaTextSize(e) {
  const F = SKICA_FONTS[e.bold === false ? 'sans' : 'bold'], H = F.g.H;
  let cap = 0; for (const c of H[1]) for (let i = 1; i < c.length; i += 2) cap = Math.max(cap, c[i]);
  const k = (e.h || 0) / (cap || 730), sp = Number(e.sp) || 0, lines = String(e.s || '').split('\n');
  const w = Math.max(0, ...lines.map(l => [...l].reduce((t, ch) => t + ((F.g[ch] || F.g['?'])[0] * k + sp), 0) - (l.length ? sp : 0)));
  return { w, h: (e.h || 0) * (1 + 1.5 * (lines.length - 1)) };
}
if (typeof module !== 'undefined') module.exports = { SKICA_FONTS, skicaTextLoops, skicaTextSize };
